from collections import Counter
seen_sigs=[]
def visible_sigs():
 root=ET.fromstring(driver.page_source)
 out=[]
 for e in root.iter():
  a=e.attrib
  if a.get('resource-id','').endswith('/card_text_view_title'):
   # parent contains title/description/source
   p=None
   for cand in root.iter():
    if e in list(cand): p=cand; break
   vals={}
   if p is not None:
    for x in p.iter():
     rid=x.attrib.get('resource-id','')
     if rid.endswith('/card_text_view_title'): vals['title']=x.attrib.get('text','')
     elif rid.endswith('/card_text_view_description'): vals['description']=x.attrib.get('text','')
     elif rid.endswith('/card_text_view_source'): vals['source']=x.attrib.get('text','')
   out.append((vals.get('title',''),vals.get('description',''),vals.get('source','')))
 return out
windows=[]
for n in range(5):
 v=visible_sigs(); windows.append(v)
 for s in v:
  if s not in seen_sigs: seen_sigs.append(s)
 driver.swipe(540,2000,540,650,450)
import time; time.sleep(.5)
v=visible_sigs(); windows.append(v)
for s in v:
 if s not in seen_sigs: seen_sigs.append(s)
{'windows':windows,'uniqueVisibleSignatures':seen_sigs,'last':v}

